commands.text:
TAG_VERSION="${GITHUB_REF_NAME#v}"
awk -v ver="$TAG_VERSION" '
  $0 ~ "^## \\[" ver "\\]" { grab=1; next }
  grab && /^## \[/ { exit }
  grab { print }
' CHANGELOG.md > release-notes.md
if [ ! -s release-notes.md ]; then
  echo "No CHANGELOG section for ${TAG_VERSION}; falling back to tag name." > release-notes.md
fi
